// Template settings: change them here, in one place.
const CONFIG = {
  llm_base_url: 'https://api.openai.com/v1',   // any OpenAI-compatible API
  llm_model: 'gpt-4o-mini',
  threshold: 0.7,                               // confidence threshold for auto-reply
  manager_chat_id: 'MANAGER_CHAT_ID',           // manager Telegram chat
};

const raw = $input.first().json;
const body = raw.body || raw;
const message = String(body.message || body.text || '').replace(/\s+/g, ' ').trim().slice(0, 2000);
const now = new Date();
const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');

return [{
  json: {
    ...CONFIG,
    message,
    session_id: String(body.session_id || 'anon-' + now.getTime()),
    channel: String(body.channel || 'web'),
    customer_name: String(body.name || ''),
    ticket_id: 'T-' + stamp + '-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
    received_at: now.toISOString(),
  },
}];

// Knowledge base of the “North Ladle” cookware store.
// In production this is replaced with a query to Notion, Google Docs or a vector DB.
const KB = [
  { id: 'kb-01', title: 'Shipping', keywords: ['delivery', 'deliver', 'shipping', 'ship', 'courier', 'post', 'delivery cost'],
    text: 'We ship by courier and to pickup points nationwide. Local delivery is $5, free over $60. Other regions take 2–7 business days, the cost is calculated in the cart.' },
  { id: 'kb-02', title: 'Pickup', keywords: ['pickup', 'pick up', 'collect', 'warehouse', 'address'],
    text: 'Pickup from the warehouse: 12 Factory St, Mon–Fri 10:00–19:00. Orders are ready 2 hours after confirmation and held for 5 days.' },
  { id: 'kb-03', title: 'Payment methods', keywords: ['payment', 'pay', 'card', 'paypal', 'cash', 'invoice', 'apple pay'],
    text: 'Pay by card, Apple Pay or PayPal on the site, or cash/card on delivery. Businesses can pay by invoice.' },
  { id: 'kb-04', title: 'Returns and exchanges', keywords: ['return', 'refund', 'exchange', 'send back', 'did not fit', 'not fit'],
    text: 'Items in good condition can be returned within 14 days with the packaging and receipt. Submit a request in your account, and we refund within 10 days after receiving the item.' },
  { id: 'kb-05', title: 'Warranty', keywords: ['warranty', 'guarantee', 'broken', 'broke', 'defect', 'crack', 'damaged'],
    text: 'Cookware has a 12-month warranty, cast iron 5 years. If it’s defective, send a photo and the order number and we’ll replace it or refund.' },
  { id: 'kb-06', title: 'Order status', keywords: ['status', 'where is my order', 'track', 'tracking', 'order number', 'when will', 'arrive'],
    text: 'Status and tracking number are in your account under “My orders”. Tracking is sent by SMS once the order ships.' },
  { id: 'kb-07', title: 'Cast iron care', keywords: ['cast iron', 'skillet', 'pan', 'rust', 'season', 'care', 'wash'],
    text: 'Wash cast iron without harsh detergents and dry it right away. Every few months, season it with a thin layer of oil. Not dishwasher safe.' },
];

const stem = w => w.toLowerCase().slice(0, 5);
const words = s => s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length >= 3);

const q = $input.first().json;
const qStems = new Set(words(q.message).map(stem));

const scored = KB.map(a => {
  const hits = a.keywords.filter(k => words(k).every(w => qStems.has(stem(w)))).length;
  return { ...a, score: Math.min(1, hits / 2) };
}).filter(a => a.score > 0).sort((a, b) => b.score - a.score).slice(0, 2);

const context = scored.length
  ? scored.map(a => `[${a.id}] ${a.title}: ${a.text}`).join('\n')
  : 'No matching articles found.';

const llm_request = {
  model: q.llm_model,
  temperature: 0.2,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content:
      'You are a support assistant for an online store. Reply in the customer’s language, briefly and politely, using only the knowledge base articles. ' +
      'If the articles have no answer, don’t make one up. Return JSON: {"answer": string, "confidence": number from 0 to 1, "article_ids": string[]}.' },
    { role: 'user', content: `Knowledge base articles:\n${context}\n\nCustomer question: ${q.message}` },
  ],
};

return [{ json: { ...q, kb_hits: scored.map(a => ({ id: a.id, title: a.title, score: a.score })), kb_score: scored[0]?.score || 0, llm_request } }];

// Parse the LLM reply and decide: auto-reply or manager handoff.
const q = $('Knowledge base search').first().json;
const res = $input.first().json;

const FORCE_WORDS = ['operator', 'manager', 'human', 'complain', 'lawsuit', 'court', 'money back'];
const text = q.message.toLowerCase();
const forced = FORCE_WORDS.find(w => new RegExp('(^|[^a-z])' + w).test(text));

let answer = '', llmConf = 0, articleIds = [], llmError = '';
try {
  if (res.error) throw new Error(typeof res.error === 'string' ? res.error : (res.error.message || 'llm_error'));
  const content = res.choices?.[0]?.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  answer = String(parsed?.answer || '').trim();
  llmConf = Math.max(0, Math.min(1, Number(parsed?.confidence) || 0));
  articleIds = Array.isArray(parsed?.article_ids) ? parsed.article_ids : [];
} catch (e) {
  llmError = String(e.message || e).slice(0, 200);
}

// Final confidence: model score plus knowledge base match.
const confidence = q.kb_score === 0 || llmError || !answer ? 0 : Math.round((0.6 * llmConf + 0.4 * q.kb_score) * 100) / 100;

let reason = '';
if (!q.message) reason = 'empty message';
else if (forced) reason = `customer asks for a human or complains (“${forced}”)`;
else if (llmError) reason = 'LLM error: ' + llmError;
else if (q.kb_score === 0) reason = 'no knowledge base article';
else if (confidence < q.threshold) reason = `low confidence ${confidence}`;

return [{ json: {
  ...q,
  answer,
  llm_confidence: llmConf,
  article_ids: articleIds,
  confidence,
  force_handoff: Boolean(forced || llmError || !q.message),
  handoff_reason: reason,
  handoff: Boolean(reason),
} }];

