// One log row per request, for both branches.
const d = $('Confidence check').first().json;
return [{ json: {
  'Date': d.received_at,
  'Ticket': d.ticket_id,
  'Session': d.session_id,
  'Channel': d.channel,
  'Question': d.message,
  'Articles': d.kb_hits.map(h => h.id).join(', '),
  'Confidence': d.confidence,
  'Result': d.handoff ? 'Handed to manager' : 'Auto-reply',
  'Handoff reason': d.handoff_reason,
  'Answer': d.handoff ? '' : d.answer,
} }];

